-- Keep persisted character hair IDs compatible with the new-only Hair.wz set.
-- Existing valid new hair IDs are left untouched. Removed/zero hair IDs are
-- moved to a safe default family while preserving the color digit when possible.

UPDATE `characters`
SET `hair` = CASE
    WHEN `gender` = 1 THEN
        CASE
            WHEN MOD(`hair`, 10) BETWEEN 0 AND 7 THEN 43270 + MOD(`hair`, 10)
            ELSE 43270
        END
    ELSE
        CASE
            WHEN MOD(`hair`, 10) BETWEEN 0 AND 7 THEN 40070 + MOD(`hair`, 10)
            ELSE 40070
        END
    END
WHERE `hair` NOT IN (
    40070, 40071, 40072, 40073, 40074, 40075, 40076, 40077,
    40080, 40081, 40082, 40083, 40084, 40085, 40086, 40087,
    42100, 42101, 42102, 42103, 42104, 42105, 42106, 42107,
