UPDATE `playernpcs`
SET `hair` = CASE
    WHEN `gender` = 1 THEN
        CASE
            WHEN MOD(COALESCE(`hair`, 0), 10) BETWEEN 0 AND 7 THEN 43270 + MOD(COALESCE(`hair`, 0), 10)
            ELSE 43270
        END
    ELSE
        CASE
            WHEN MOD(COALESCE(`hair`, 0), 10) BETWEEN 0 AND 7 THEN 40070 + MOD(COALESCE(`hair`, 0), 10)
            ELSE 40070
        END
    END
WHERE `hair` IS NULL
